import { RateLimitError } from "./types.js";

export function clusterKey(id: string): string {
  if (id.length === 0) throw new RateLimitError("id must be non-empty");
  if (/[{}]/.test(id)) throw new RateLimitError("id must not contain { or }");
  return `{${id}}`;
}

