// illustrative, NOT in the repo: a local pre-check in front of Redis (abuse never reaches Redis)
class TwoTierStore implements Store {
  constructor(private readonly local: Store, private readonly shared: Store) {}
  async consume<S>(algorithm: Algorithm<S>, key: string, cost: number): Promise<Decision> {
    const l = await this.local.consume(algorithm, key, cost);
    if (!l.allowed) return l;              // already over the limit on this instance alone
    return this.shared.consume(algorithm, key, cost); // the real, shared decision
  }
}

